	@ParameterizedTest
	@ValueSource(strings = { "exact-filter", "generalized-filter", "semi-anti" })
	void legacyPopulationSurfacesDistinguishEffectiveRawKinds(String route) {
		Filter plain = filter(pattern(false));
		Filter restricted = filter(pattern(true));
		Object plainKey;
		Object restrictedKey;
		if (route.equals("semi-anti")) {
			plainKey = SemiAntiSurfaceKey.from(exists(pattern(false)), "EXISTS", "streaming-correlated");
			restrictedKey = SemiAntiSurfaceKey.from(exists(pattern(true)), "EXISTS", "streaming-correlated");
		} else if (route.equals("exact-filter")) {
			plainKey = FilterSurfaceKey.exact(plain);
			restrictedKey = FilterSurfaceKey.exact(restricted);
		} else {
			plainKey = FilterSurfaceKey.generalized(plain);
			restrictedKey = FilterSurfaceKey.generalized(restricted);
		}
		assertNotNull(plainKey);
		assertNotNull(restrictedKey);
		assertNotEquals(plainKey, restrictedKey);
	}

