	@Test
	void reopenedOldRestrictedMappedExactZeroMissesTheCurrentUnrestrictedNamespace() throws Exception {
		LmdbEstimatorRuntime runtime = mock(LmdbEstimatorRuntime.class);
		var current = contract(pattern(false), runtime);
		var descriptor = (LmdbRuntimeFeedbackDescriptor) current.descriptor();
		String raw = LeoOperatorKey.from(pattern(true)).structuralFingerprint();
		assertEquals(raw, LeoOperatorKey.from(pattern(false)).structuralFingerprint(),
				"the old generic key omitted the executable restriction");
		String[] fields = descriptor.logicalKey().externalForm().split("\\|", -1);
		LogicalLearningKey old = LogicalLearningKey.of("statement-pattern", LearningKeyCodec.digest(raw),
				LearningKeyCodec.digest(""), LearningKeyCodec.digest(raw), LearningKeyCodec.decode(fields[5]),
				"none", "bag|duplicate-sensitive|sparql-unbound", LearningKeyCodec.decode(fields[8]));
		String applicability = descriptor.applicability().externalForm();
		LearningApplicability oldApplicability = LearningApplicability.parse(
				applicability.substring(0, applicability.lastIndexOf('|') + 1) + "1");
		var oldDescriptor = new LmdbRuntimeFeedbackDescriptor(descriptor.legacyLogicalKey(),
				descriptor.legacyPhysicalKey(), old, oldApplicability, descriptor.physicalKey(),
				descriptor.logicalGroupOrigin(), descriptor.featureEnvelope(), descriptor.exactFilterSurfaceKey(),
				descriptor.generalizedFilterSurfaceKey());
		Path path = estimatorPath("old-mapped");
		LmdbOperatorFeedbackStats feedback = stats(path);
		publish(feedback, current.withDescriptor(oldDescriptor), 0L);
		feedback.persistIfDirty();
		LmdbOperatorFeedbackStats reopened = stats(path);
		assertEquals(0.0d, reopened.exactCardinalityFact(old, oldApplicability),
				"the separately addressed old record remains readable without a store wipe");
		when(runtime.feedback()).thenReturn(reopened);
		assertNotEquals(old,
				((LmdbRuntimeFeedbackDescriptor) contract(pattern(false), runtime).descriptor()).logicalKey());
		assertEquals(10.0d, estimate(pattern(false), runtime).outputRows());
		publish(reopened, contract(pattern(false), runtime), 5L);
		publish(reopened, contract(pattern(true), runtime), 2L);
		assertEquals(5.0d, estimate(pattern(false), runtime).outputRows());
		assertEquals(2.0d, estimate(pattern(true), runtime).outputRows());
	}

	@ParameterizedTest
	@ValueSource(strings = { "operator", "semi-anti" })
	void capturedPreFixRestrictedSidecarMissesCurrentUnrestrictedAndAllowsFreshReuse(String kind) throws Exception {
		Path path = estimatorPath("captured-old-" + kind);
		try (var input = getClass().getResourceAsStream("legacy-semantic-kind-" + kind + "-v24.base64")) {
			assertNotNull(input);
			Files.write(path.resolveSibling(path.getFileName() + ".operators"),
					Base64.getMimeDecoder().decode(input.readAllBytes()));
		}
		LmdbOperatorFeedbackStats feedback = stats(path);
		assertTrue(feedback.planningRevision() > 0L,
				"the compatible old snapshot must be loaded rather than discarded");
		if (kind.equals("operator")) {
			assertNull(feedback.estimate(joined(pattern(false)), 200.0d, 100.0d, 10.0d, 20.0d));
			Join fresh = joined(pattern(false));
			complete(fresh);
			feedback.recordOperatorOutcome(fresh);
			assertNotNull(feedback.estimate(joined(pattern(false)), 200.0d, 100.0d, 10.0d, 20.0d));
		} else {
			assertNull(feedback.semiAntiEstimate(exists(pattern(false)), "EXISTS", "streaming-correlated"));
			feedback.recordSemiAntiOutcome(exists(pattern(false)), new EvaluationStatistics.SemiAntiOutcomeObservation(
					"EXISTS", "streaming-correlated", "streaming-correlated", 5L, 0L, 5L,
					5L, 0L, 5L, 0L, 5L, 5L, 5L, 0L, 0L, 0L, true, "", ""));
			assertNotNull(feedback.semiAntiEstimate(exists(pattern(false)), "EXISTS", "streaming-correlated"));
		}
		feedback.persistIfDirty();
		LmdbOperatorFeedbackStats reopened = stats(path);
		if (kind.equals("operator")) {
			assertNotNull(reopened.estimate(joined(pattern(false)), 200.0d, 100.0d, 10.0d, 20.0d));
		} else {
			assertNotNull(reopened.semiAntiEstimate(exists(pattern(false)), "EXISTS", "streaming-correlated"));
		}
	}

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void realNativeUnionKeepsRestrictedAndUnrestrictedBagsAcrossWarmReuse(boolean variableOverride) {
		SailRepository repository = new SailRepository(new LmdbStore(temporary.resolve("native").toFile()));
		repository.init();
		try (var connection = repository.getConnection()) {
			var values = connection.getValueFactory();
			connection.add(values.createIRI("urn:test:literal"), values.createIRI("urn:test:p"),
					values.createLiteral("literal"));
			connection.add(values.createIRI("urn:test:iri"), values.createIRI("urn:test:p"),
					values.createIRI("urn:test:object"));
			for (int invocation = 0; invocation < 2; invocation++) {
				StatementPattern restricted = pattern(true);
				if (variableOverride) {
					restricted.setStringMetricPlanned(LmdbValueIdFilter.PLANNED_ID_FILTER, "object:IRI");
					restricted.getObjectVar()
							.setStringMetricPlanned(LmdbValueIdFilter.PLANNED_ID_FILTER, "object:LITERAL");
				}
				List<String> rows = new ArrayList<>();
				try (var result = connection.getSailConnection()
						.evaluate(new Union(restricted, pattern(false)),
								null, EmptyBindingSet.getInstance(), false)) {
					while (result.hasNext()) {
						rows.add(result.next().getValue("s").stringValue());
					}
				}
				rows.sort(String::compareTo);
				assertEquals(List.of("urn:test:iri", "urn:test:literal", "urn:test:literal"), rows);
			}
		} finally {
			repository.shutDown();
		}
	}

	@ParameterizedTest
	@ValueSource(ints = { 0, 1, 2, 3 })
	void semanticCopiesPreserveNestedOverrideAndRepeatedBindingsWithoutChangingTheCaller(int route) throws Exception {
		Var subject = Var.of("s");
		Var object = Var.of("s");
		StatementPattern restricted = new StatementPattern(subject,
				Var.of("p", SimpleValueFactory.getInstance().createIRI("urn:test:p")), object, Var.of("g"));
		restricted.setStringMetricPlanned(LmdbValueIdFilter.PLANNED_ID_FILTER, "object:IRI");
		restricted.getObjectVar().setStringMetricPlanned(LmdbValueIdFilter.PLANNED_ID_FILTER, "object:LITERAL");
		restricted.setIndependentInputScope(true);
		restricted.setContextBindingOriginInherited(true);
		assertTrue(restricted.isContextBindingOriginInherited());
		StatementPattern plain = pattern(false);
		TupleExpr original = new Union(plain, new Filter(restricted, new Exists(pattern(false))));
		TupleExpr copied = LmdbValueIdFilter.semanticClone(original);
		if (route == 1 || route == 3) {
			copied = copied.clone();
		}
		if (route == 2 || route == 3) {
			ByteArrayOutputStream bytes = new ByteArrayOutputStream();
			try (ObjectOutputStream output = new ObjectOutputStream(bytes)) {
				output.writeObject(copied);
			}
			try (ObjectInputStream input = new ObjectInputStream(new ByteArrayInputStream(bytes.toByteArray()))) {
				copied = (TupleExpr) input.readObject();
			}
		}
		List<StatementPattern> originalPatterns = statementPatterns(original);
		List<StatementPattern> copiedPatterns = statementPatterns(copied);
		assertEquals(
				originalPatterns.stream()
						.map(p -> LmdbValueIdFilter.fromStatementPattern(p).semanticKindWord())
						.toList(),
				copiedPatterns.stream()
						.map(p -> LmdbValueIdFilter.fromStatementPattern(p).semanticKindWord())
						.toList());
		StatementPattern copiedRestriction = copiedPatterns.stream()
				.filter(StatementPattern::isIndependentInputScope)
				.findFirst()
				.orElseThrow();
		assertTrue(copiedRestriction.isContextBindingOriginInherited());
		assertEquals("object:IRI", restricted.getStringMetricPlanned(LmdbValueIdFilter.PLANNED_ID_FILTER));
		assertEquals("object:LITERAL",
				restricted.getObjectVar().getStringMetricPlanned(LmdbValueIdFilter.PLANNED_ID_FILTER));
		assertSame(subject, restricted.getSubjectVar());
		assertSame(object, restricted.getObjectVar());
		assertEquals(subject.getName(), object.getName());
		assertNull(plain.getStringMetricPlanned(LmdbValueIdFilter.PLANNED_ID_FILTER));
	}

	private static List<StatementPattern> statementPatterns(TupleExpr source) {
		List<StatementPattern> result = new ArrayList<>();
		source.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(StatementPattern pattern) {
				result.add(pattern);
			}
		});
		return result;
	}

	@Test
	void unknownStatementSubclassCannotClaimTheCertifiedCarrierClassTransition() {
		StatementPattern unknown = new StatementPattern(Var.of("s"),
				Var.of("p", SimpleValueFactory.getInstance().createIRI("urn:test:p")), Var.of("o")) {
			@Override
			public StatementPattern clone() {
				return new StatementPattern(getScope(), getSubjectVar().clone(), getPredicateVar().clone(),
						getObjectVar().clone(), null);
			}
		};
		assertThrows(CascadesPlanningException.class, () -> LmdbValueIdFilter.semanticClone(unknown));
	}

	private static StatementPattern pattern(boolean restricted) {
		StatementPattern result = new StatementPattern(Var.of("s"),
				Var.of("p", SimpleValueFactory.getInstance().createIRI("urn:test:p")), Var.of("o"));
		if (restricted) {
			result.setStringMetricPlanned(LmdbValueIdFilter.PLANNED_ID_FILTER, "object:LITERAL");
		}
		return result;
	}

	private static Filter filter(StatementPattern pattern) {
		Filter result = new Filter(pattern, new ValueConstant(SimpleValueFactory.getInstance().createLiteral(true)));
		PlanningGraphDomains.capture(result, PlanningGraphDomain.defaultGraph());
		return result;
	}

	private static Filter exists(StatementPattern rhs) {
		Filter result = new Filter(pattern(false), new Exists(rhs));
		PlanningGraphDomains.capture(result, PlanningGraphDomain.defaultGraph());
		return result;
	}

	private static Join joined(StatementPattern left) {
		StatementPattern right = new StatementPattern(Var.of("s"),
				Var.of("p2", SimpleValueFactory.getInstance().createIRI("urn:test:other")), Var.of("v"));
		Join result = new Join(left, right);
		PlanningGraphDomains.capture(result, PlanningGraphDomain.defaultGraph());
		return result;
	}

	private Path estimatorPath(String name) throws Exception {
		Path path = temporary.resolve(name);
		Files.createDirectories(path);
		Files.writeString(path.resolve("metadata.bin"), "metadata");
		return path;
	}

	private static LmdbOperatorFeedbackStats stats(Path path) {
		return new LmdbOperatorFeedbackStats(path, () -> SNAPSHOT);
	}

	private static void complete(Join node) {
		node.setRuntimeTelemetryEnabled(true);
		node.setResultSizeEstimate(10.0d);
		node.setCostEstimate(20.0d);
		node.setDoubleMetricPlanned(TelemetryMetricNames.PLANNED_WORK_ROWS, 20.0d);
		node.setResultSizeActual(0L);
		node.setLongMetricActual(TelemetryMetricNames.OUTPUT_ROWS_ACTUAL, 0L);
		node.setLongMetricActual(TelemetryMetricNames.CLOSE_COUNT_ACTUAL, 1L);
		node.setLongMetricActual(TelemetryMetricNames.EXHAUSTED_CLOSE_COUNT_ACTUAL, 1L);
		node.setHasNextCallCountActual(1L);
		node.setHasNextTrueCountActual(0L);
		node.setJoinLeftBindingsConsumedActual(50L);
		node.setJoinRightBindingsConsumedActual(100L);
	}

	private static RuntimeFeedbackContract contract(StatementPattern pattern, LmdbEstimatorRuntime runtime) {
		return estimate(pattern, runtime).runtimeFeedbackContract();
	}

	private static PackedCostEstimate estimate(StatementPattern pattern, LmdbEstimatorRuntime runtime) {
		var call = PackedCostTestSupport.unaryOperator(PlanningGraphDomain.defaultGraph(), filter(pattern),
				LmdbStatementPatternSemanticsCodec.INSTANCE);
		var output = new PackedCostEstimate();
		output.setContextualRows(10.0d, 10.0d);
		new LmdbMappedFrontierLearningSession(runtime, call.query(), true).applyLeaf(call.inputRelationId(),
				PackedCostTestSupport.prefixContext(new int[0], 0, 1.0d, 0), output);
		return output;
	}

	private static void publish(LmdbOperatorFeedbackStats feedback, RuntimeFeedbackContract contract, long rows) {
		RuntimeFeedbackTarget target = feedback.resolveRuntimeFeedbackTarget(contract);
		target.open();
		target.close(rows, rows, rows, 0L, 0L, 0L, 0L, 0L, 0L, 0L,
				EvaluationStatistics.TerminationClassification.EXHAUSTED);
		target.recordActualPhysicalImplementation(contract.physicalImplementationId());
		feedback.publishRuntimeFeedbackTargets(new RuntimeFeedbackTarget[] { target }, 1, true);
	}
